package thaumcraft.verification;
import java.util.*;import java.nio.file.*;import com.google.gson.GsonBuilder;import com.mojang.authlib.GameProfile;
import net.minecraft.core.*;import net.minecraft.server.*;import net.minecraft.world.*;import net.minecraft.world.item.context.UseOnContext;import net.minecraft.world.level.block.Blocks;import net.minecraft.world.phys.BlockHitResult;
import net.neoforged.neoforge.common.util.FakePlayer;import thaumcraft.production.InfernalFurnaceBlock;import thaumcraft.registry.R3Content;import thaumcraft.knowledge.KnowledgeService;
final class InfernalFollowupVerification {
 static void run(MinecraftServer server){var checks=new ArrayList<String>();Throwable failure=null;try{var l=server.overworld();var p=new BlockPos(0,100,0);var player=new FakePlayer(l,new GameProfile(UUID.randomUUID(),"FurnaceFollowup"));KnowledgeService.initialize(player);KnowledgeService.mutate(player,k->k.completeResearch("INFERNALFURNACE"));
 for(var facing:Direction.Plane.HORIZONTAL){var center=p.relative(facing,5);for(int y=-1;y<=1;y++)for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++){var state=Math.abs(x)==1&&Math.abs(z)==1?Blocks.NETHER_BRICKS.defaultBlockState():Blocks.OBSIDIAN.defaultBlockState();if(x==0&&z==0&&y==1)state=Blocks.AIR.defaultBlockState();if(x==0&&z==0&&y==0)state=Blocks.LAVA.defaultBlockState();if(y==0&&x==facing.getStepX()&&z==facing.getStepZ())state=Blocks.IRON_BARS.defaultBlockState();l.setBlockAndUpdate(center.offset(x,y,z),state);}
 if(InfernalFurnaceBlock.fits(l,center)!=facing)throw new AssertionError("literal original iron-bars mask failed "+facing);checks.add("TC4 literal layers: top air, middle lava/iron bars, solid bottom "+facing);
 var grille=center.relative(facing);l.setBlockAndUpdate(grille,Blocks.NETHER_BRICK_FENCE.defaultBlockState());if(InfernalFurnaceBlock.fits(l,center)!=null)throw new AssertionError("nether fence incorrectly accepted");checks.add("nether brick fence rejected "+facing);l.setBlockAndUpdate(grille,Blocks.IRON_BARS.defaultBlockState());l.setBlockAndUpdate(center.above(),Blocks.OBSIDIAN.defaultBlockState());if(InfernalFurnaceBlock.fits(l,center)!=null)throw new AssertionError("top opening filled");checks.add("blocked top opening rejected "+facing);l.setBlockAndUpdate(center.above(),Blocks.AIR.defaultBlockState());
 var wand=Round3Verification.wand();player.setItemInHand(InteractionHand.MAIN_HAND,wand);if(!wand.getItem().useOn(new UseOnContext(player,InteractionHand.MAIN_HAND,new BlockHitResult(grille.getCenter(),facing,grille,false))).consumesAction()||!l.getBlockState(center).is(R3Content.INFERNAL_FURNACE.get()))throw new AssertionError("actual wand click on iron bars failed");checks.add("wand click on iron bars forms furnace "+facing);InfernalFurnaceBlock.restore(l,center,new BlockPos(50,50,50),facing);if(!l.getBlockState(grille).is(Blocks.IRON_BARS)||!l.isEmptyBlock(center.above()))throw new AssertionError("restore wrong parts");checks.add("dismantled furnace restores iron bars and top air "+facing);for(var q:BlockPos.betweenClosed(center.offset(-1,-1,-1),center.offset(1,1,1)))l.removeBlock(q,false);
 }
 }catch(Throwable error){failure=error;thaumcraft.Thaumcraft.LOGGER.error("Furnace followup",error);}try{var data=new LinkedHashMap<String,Object>();data.put("passed",failure==null);data.put("checks",checks);data.put("count",checks.size());if(failure!=null)data.put("error",failure.toString());Files.writeString(Path.of(System.getProperty("thaumcraft.r3.root"),"analysis/golems-aura-tools-audit/round3-followup/server-result.json"),new GsonBuilder().setPrettyPrinting().create().toJson(data));}catch(Exception error){throw new RuntimeException(error);}server.halt(false);}
}
